The loop in `escape_string`:
```cpp
for (const CharT* it = begin; it != end; ++it)
{
    CharT c = *it;
    switch (c)
    {
        ...
        default:
            if (escape_solidus && c == '/') {...}
            else if (is_control_character(c) || escape_all_non_ascii)
            {
                uint32_t cp;
                auto r = unicode_traits::to_codepoint(it, end, cp, strict);
                if (r.ec != conv_errc())
                {
                    JSONCONS_THROW(ser_error(json_errc::illegal_codepoint));
                }
                it = r.ptr;
                ...
            }
            else
            {
                sink.push_back(c);
                ++count;
            }
